package local.ondemand;
import android.content.*;import org.json.*;import java.util.*;
/** Per-device watchlist and explicit tastes; provider credentials never enter this store. */
final class CinemaLibrary {
 static SharedPreferences prefs(MainActivity a){return a.getSharedPreferences("cinema-library",0);}
 static String key(JSONObject m,String type){return type+":"+m.optString("id");}
 static JSONObject compact(JSONObject m,String type){JSONObject out=new JSONObject();for(String name:new String[]{"id","name","poster","background","logo","description","genres","director","creator","cast","releaseInfo","runtime","imdbRating"})try{if(m.has(name))out.put(name,m.opt(name));}catch(Exception ignored){}try{out.put("type",type);}catch(Exception ignored){}return out;}
 static boolean saved(MainActivity a,JSONObject m,String t){return prefs(a).contains("list."+key(m,t));}
 static int rating(MainActivity a,JSONObject m,String t){return prefs(a).getInt("rating."+key(m,t),0);}
 static void toggle(MainActivity a,JSONObject m,String t){String k=key(m,t);SharedPreferences.Editor e=prefs(a).edit();if(saved(a,m,t))e.remove("list."+k);else e.putString("list."+k,compact(m,t).toString());e.apply();}
 static void rate(MainActivity a,JSONObject m,String t,int n){String k=key(m,t);prefs(a).edit().putInt("rating."+k,n).putString("taste."+k,compact(m,t).toString()).apply();}
 static List<JSONObject> list(MainActivity a,boolean liked){List<JSONObject> out=new ArrayList<>();for(Map.Entry<String,?> e:prefs(a).getAll().entrySet())try{if(e.getKey().startsWith(liked?"taste.":"list.")){JSONObject m=new JSONObject(String.valueOf(e.getValue()));if(!liked||rating(a,m,m.optString("type","movie"))>0)out.add(m);}}catch(Exception ignored){}out.sort((x,y)->x.optString("name").compareToIgnoreCase(y.optString("name")));return out;}
 static JSONArray ranked(MainActivity a,JSONArray data,String type){List<JSONObject> titles=new ArrayList<>(),likes=list(a,true);if(data!=null)for(int i=0;i<data.length();i++){JSONObject m=data.optJSONObject(i);if(m!=null&&rating(a,m,type)>=0)titles.add(m);}titles.sort((x,y)->Integer.compare(score(y,likes,type),score(x,likes,type)));JSONArray result=new JSONArray();for(JSONObject m:titles)result.put(m);return result;}
 static int score(JSONObject m,List<JSONObject> liked,String type){int n=0;for(JSONObject t:liked)if(t.optString("type").equals(type)){n+=SimilarMovies.shared(SimilarMovies.values(t,"genres"),SimilarMovies.values(m,"genres"))*4;n+=SimilarMovies.shared(SimilarMovies.values(t,"director"),SimilarMovies.values(m,"director"))*8;n+=Math.min(3,SimilarMovies.shared(SimilarMovies.values(t,"cast"),SimilarMovies.values(m,"cast")));}return n;}
 static void ratingMenu(MainActivity a,JSONObject m,String type,Runnable changed){new android.app.AlertDialog.Builder(a).setTitle("Your rating · "+m.optString("name")).setItems(new String[]{"Like · suggest more like this","Not for me · hide from recommendations","Clear rating"},(d,n)->{rate(a,m,type,n==0?1:n==1?-1:0);changed.run();}).setNegativeButton("Cancel",null).show();}
 static void menu(MainActivity a,JSONObject m,String type,Runnable changed){List<String> options=new ArrayList<>();if(type.equals("movie"))options.add(WatchLibrary.watched(a,m.optString("id"))?"Mark unwatched":"Mark watched");options.add(saved(a,m,type)?"Remove from My List":"Add to My List");options.add("Rate this title");options.add("More information");new android.app.AlertDialog.Builder(a).setTitle(m.optString("name")).setItems(options.toArray(new String[0]),(d,n)->{String selected=options.get(n);if(selected.startsWith("Mark ")){String id=m.optString("id");WatchLibrary.mark(a,id,!WatchLibrary.watched(a,id));changed.run();}else if(selected.contains("My List")){toggle(a,m,type);changed.run();}else if(selected.equals("Rate this title"))ratingMenu(a,m,type,changed);else information(a,m,type);}).setNegativeButton("Close",null).show();}
 static void information(MainActivity a,JSONObject m,String type){String nl=String.valueOf((char)10);String facts=SelectionInfo.value(m,"genres");String body=m.optString("releaseInfo")+(m.optString("runtime").isEmpty()?"":" · "+m.optString("runtime"))+(facts.isEmpty()?"":nl+facts)+nl+nl+m.optString("description","Choose this title to see its full information.");String cast=SelectionInfo.value(m,"cast");if(!cast.isEmpty())body+=nl+nl+"Cast: "+cast;new android.app.AlertDialog.Builder(a).setTitle(m.optString("name")).setMessage(body).setPositiveButton(type.equals("series")?"View episodes":"Choose source",(d,n)->{a.selected=m;a.type=type;a.go(a::detail);}).setNeutralButton(saved(a,m,type)?"Remove from My List":"+ My List",(d,n)->toggle(a,m,type)).setNegativeButton("Close",null).show();}
 static void hub(MainActivity a){a.current=()->hub(a);a.screen("My Cinema","Your saved titles, likes and recently watched");hubShelf(a,"My List",list(a,false),"saved");hubShelf(a,"Titles you like",list(a,true),"liked");hubShelf(a,"Recently watched",WatchLibrary.recent(a),"recent");}
 static void hubShelf(MainActivity a,String heading,List<JSONObject> titles,String kind){TextViewCompat.heading(a,heading);if(titles.isEmpty()){a.rows.addView(a.text(kind.equals("saved")?"Add titles from a poster's hold menu or the featured + My List button.":"Nothing here yet.",13));return;}HorizontalScrollViewCompat.add(a,titles,kind);}
 static final class TextViewCompat {static void heading(MainActivity a,String title){android.widget.TextView v=a.text(title,19);v.setPadding(0,a.dp(16),0,a.dp(8));a.rows.addView(v);}}
 static final class HorizontalScrollViewCompat {static void add(MainActivity a,List<JSONObject> data,String kind){android.widget.HorizontalScrollView scroll=new android.widget.HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);android.widget.LinearLayout row=new android.widget.LinearLayout(a);scroll.addView(row);a.rows.addView(scroll);for(JSONObject m:data){String type=m.optString("type","movie");ViewCompat.card(a,row,m,type,kind);}}}
 static final class ViewCompat {static void card(MainActivity a,android.widget.LinearLayout row,JSONObject m,String type,String kind){android.view.View card=PosterCard.create(a,m,"library:"+kind+":"+type+":"+m.optString("id"),()->{a.selected=m;a.type=type;a.go(a::detail);});card.setOnLongClickListener(v->{menu(a,m,type,()->hub(a));return true;});android.widget.LinearLayout.LayoutParams p=new android.widget.LinearLayout.LayoutParams(a.dp(112),a.dp(194));p.rightMargin=a.dp(9);row.addView(card,p);}}
}
